sp_widget.client_script:
api.controller=function($scope) {
	var c = this;

	// Initialize
	c.selectedPuzzle = null;
	c.grid = [];
	c.currentCell = null;
	c.isComplete = false;

	// Select puzzle and reload widget with puzzle data
	c.selectPuzzle = function() {
		if (c.selectedPuzzle) {
			// Pass puzzle_id to server via input parameter
			c.server.get({puzzle_id: c.selectedPuzzle}).then(function() {
				initializeGrid();
			});
		}
	};

	// Initialize grid from server data
	function initializeGrid() {
		if (c.data.grid) {
			c.grid = c.data.grid.map(function(cell) {
				return {
					row: cell.row,
					col: cell.col,
					isBlank: cell.isBlank,
					userLetter: '',
					correctLetter: cell.correctLetter,
					isCorrect: false,
					isIncorrect: false
				};
			});
		}
	}

	// Handle cell click
	c.selectCell = function(cell) {
		if (!cell.isBlank) {
			c.currentCell = cell;
		}
	};

	// Handle keyboard input
	c.handleKeyDown = function(event, cell) {
		if (cell.isBlank) return;

		var key = event.key;

		// Handle letter input
		if (/^[a-zA-Z]$/.test(key)) {
			event.preventDefault();
			cell.userLetter = key.toUpperCase();
			checkCell(cell);
			moveToNextCell(cell);
		}
		// Handle backspace/delete
		else if (key === 'Backspace' || key === 'Delete') {
			event.preventDefault();
			cell.userLetter = '';
			cell.isCorrect = false;
			cell.isIncorrect = false;
			if (key === 'Backspace') {
				moveToPreviousCell(cell);
			}
		}
		// Handle arrow keys
		else if (key === 'ArrowRight') {
			event.preventDefault();
			moveToNextCell(cell);
		}
		else if (key === 'ArrowLeft') {
			event.preventDefault();
			moveToPreviousCell(cell);
		}
		else if (key === 'ArrowDown') {
			event.preventDefault();
			moveCellVertical(cell, 1);
		}
		else if (key === 'ArrowUp') {
			event.preventDefault();
			moveCellVertical(cell, -1);
		}
	};

	// Check if letter is correct
	function checkCell(cell) {
		if (cell.userLetter === cell.correctLetter) {
			cell.isCorrect = true;
			cell.isIncorrect = false;
		} else if (cell.userLetter !== '') {
			cell.isCorrect = false;
			cell.isIncorrect = true;
		} else {
			cell.isCorrect = false;
			cell.isIncorrect = false;
		}

		checkCompletion();
	}

	// Check if puzzle is complete
	function checkCompletion() {
		var allCorrect = true;
		for (var i = 0; i < c.grid.length; i++) {
			if (!c.grid[i].isBlank) {
				if (!c.grid[i].isCorrect) {
					allCorrect = false;
					break;
				}
			}
		}
		c.isComplete = allCorrect;
	}

	// Navigate to next cell (horizontal)
	function moveToNextCell(currentCell) {
		var nextCol = currentCell.col + 1;
		var nextRow = currentCell.row;

		// Wrap to next row
		if (nextCol > 5) {
			nextCol = 1;
			nextRow++;
		}

		if (nextRow <= 5) {
			var nextCell = findCell(nextRow, nextCol);
			if (nextCell && !nextCell.isBlank) {
				focusCell(nextCell);
			} else if (nextRow < 5 || nextCol < 5) {
				// Try next cell if current is blank
				moveToNextCell({row: nextRow, col: nextCol});
			}
		}
	}

	// Navigate to previous cell (horizontal)
	function moveToPreviousCell(currentCell) {
		var prevCol = currentCell.col - 1;
		var prevRow = currentCell.row;

		// Wrap to previous row
		if (prevCol < 1) {
			prevCol = 5;
			prevRow--;
		}

		if (prevRow >= 1) {
			var prevCell = findCell(prevRow, prevCol);
			if (prevCell && !prevCell.isBlank) {
				focusCell(prevCell);
			} else if (prevRow > 1 || prevCol > 1) {
				// Try previous cell if current is blank
				moveToPreviousCell({row: prevRow, col: prevCol});
			}
		}
	}

	// Navigate vertically
	function moveCellVertical(currentCell, direction) {
		var nextRow = currentCell.row + direction;
		var nextCol = currentCell.col;

		if (nextRow >= 1 && nextRow <= 5) {
			var nextCell = findCell(nextRow, nextCol);
			if (nextCell && !nextCell.isBlank) {
				focusCell(nextCell);
			}
		}
	}

	// Find cell by row/col
	function findCell(row, col) {
		for (var i = 0; i < c.grid.length; i++) {
			if (c.grid[i].row === row && c.grid[i].col === col) {
				return c.grid[i];
			}
		}
		return null;
	}

	// Focus on a cell
	function focusCell(cell) {
		c.currentCell = cell;
		$scope.$applyAsync(function() {
			var cellElement = document.getElementById('cell-' + cell.row + '-' + cell.col);
			if (cellElement) {
				cellElement.focus();
			}
		});
	}

	// Get cell index for ng-repeat
	c.getCellIndex = function(row, col) {
		return (row - 1) * 5 + (col - 1);
	};

	// Initialize on load if a puzzle is already selected
	if (c.data.selectedPuzzleId) {
		c.selectedPuzzle = c.data.selectedPuzzleId;
		initializeGrid();
	}
};

sp_widget.css:
.mini-crossword-container {
	max-width: 800px;
	margin: 0 auto;
	padding: 20px;
}

/* Puzzle Selector */
.puzzle-selector {
	background: #f8f9fa;
	padding: 20px;
	border-radius: 8px;
	margin-bottom: 30px;
}

.puzzle-selector h2 {
	margin-top: 0;
	margin-bottom: 15px;
	color: #333;
}

/* Crossword Grid */
.crossword-grid {
	display: inline-block;
	border: 3px solid #000;
	background: #fff;
	box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}

.grid-row {
	display: flex;
	margin: 0;
	padding: 0;
}

.grid-cell {
	width: 50px;
	height: 50px;
	border: 1px solid #000;
	position: relative;
	display: flex;
	align-items: center;
	justify-content: center;
	background: #fff;
}

.grid-cell.blank {
	background: #000;
	border-color: #000;
}

.grid-cell.active {
	background: #fffacd;
	box-shadow: inset 0 0 0 2px #4a90e2;
}

.grid-cell.correct {
	background: #d4edda;
}

.grid-cell.incorrect {
	background: #f8d7da;
}

.cell-input {
	width: 100%;
	height: 100%;
	border: none;
	background: transparent;
	text-align: center;
	font-size: 24px;
	font-weight: bold;
	text-transform: uppercase;
	padding: 0;
	margin: 0;
	outline: none;
	color: #000;
	font-family: 'Arial', sans-serif;
	cursor: pointer;
}

.cell-input:focus {
	background: transparent;
	outline: none;
}

/* Clues Section */
.clues-container {
	margin-top: 30px;
}

.clues-container h4 {
	font-weight: bold;
	margin-bottom: 15px;
	padding-bottom: 10px;
	border-bottom: 2px solid #dee2e6;
	color: #333;
}

.clue-list {
	padding-left: 0;
}

.clue-item {
	padding: 10px;
	margin-bottom: 8px;
	background: #f8f9fa;
	border-radius: 4px;
	display: block;
	transition: background 0.2s;
}

.clue-item:hover {
	background: #e9ecef;
}

.clue-number {
	font-weight: bold;
	color: #4a90e2;
	margin-right: 8px;
	min-width: 25px;
	display: inline-block;
}

.clue-text {
	color: #333;
	font-size: 15px;
}

.clue-position {
	display: block;
	font-size: 12px;
	margin-top: 4px;
	margin-left: 33px;
}

/* Success Alert */
.alert-success {
	text-align: center;
	font-size: 18px;
	animation: slideDown 0.5s ease-out;
}

@keyframes slideDown {
	from {
		opacity: 0;
		transform: translateY(-20px);
	}
	to {
		opacity: 1;
		transform: translateY(0);
	}
}

/* Responsive Design */
@media (max-width: 768px) {
	.grid-cell {
		width: 45px;
		height: 45px;
	}

	.cell-input {
		font-size: 20px;
	}

	.clues-container .col-md-6 {
		margin-bottom: 20px;
	}
}

@media (max-width: 576px) {
	.grid-cell {
		width: 40px;
		height: 40px;
	}

	.cell-input {
		font-size: 18px;
	}
}

sp_widget.script:
(function() {
	// Server-side script - Fetch puzzle list and selected puzzle data

	// Get list of all available puzzles
	data.puzzles = [];
	var puzzleGR = new GlideRecord('x_1468549_mini_c_0_daily_puzzle');
	puzzleGR.orderByDesc('sys_created_on');
	puzzleGR.query();

	while (puzzleGR.next()) {
		var puzzleDate = puzzleGR.getValue('date');
		var puzzleType = puzzleGR.getValue('type');
		var displayName = puzzleType === 'daily' && puzzleDate ?
			'Daily - ' + puzzleDate :
			'Random #' + puzzleGR.getValue('sys_id').substring(0, 8);

		data.puzzles.push({
			sys_id: puzzleGR.getValue('sys_id'),
			name: displayName,
			type: puzzleType,
			date: puzzleDate
		});
	}

	// If puzzle is selected, load its data
	if (input && input.puzzle_id) {
		data.selectedPuzzleId = input.puzzle_id;
		data.grid = [];
		data.words = [];
		data.clues = {
			across: [],
			down: []
		};

		// Load puzzle grid
		var gridGR = new GlideRecord('x_1468549_mini_c_0_puzzle_grid');
		gridGR.addQuery('daily_puzzle', input.puzzle_id);
		gridGR.query();

		while (gridGR.next()) {
			var wordRecord = gridGR.word.getRefRecord();
			var wordText = wordRecord.getValue('word');
			var hint = wordRecord.getValue('hint') || 'No clue provided';

			var wordData = {
				sys_id: gridGR.getValue('sys_id'),
				word: wordText.toUpperCase(),
				length: wordText.length,
				row: parseInt(gridGR.getValue('row')),
				col: parseInt(gridGR.getValue('column')),
				direction: gridGR.getValue('direction'),
				hint: hint
			};

			data.words.push(wordData);

			// Organize clues by direction
			var clueNumber = wordData.direction === 'horizontal' ?
				wordData.row + '-' + wordData.col :
				wordData.col + '-' + wordData.row;

			if (wordData.direction === 'horizontal') {
				data.clues.across.push({
					number: clueNumber,
					row: wordData.row,
					col: wordData.col,
					length: wordData.length,
					hint: hint,
					word: wordData.word
				});
			} else {
				data.clues.down.push({
					number: clueNumber,
					row: wordData.row,
					col: wordData.col,
					length: wordData.length,
					hint: hint,
					word: wordData.word
				});
			}
		}

		// Sort clues by position
		data.clues.across.sort(function(a, b) {
			if (a.row !== b.row) return a.row - b.row;
			return a.col - b.col;
		});

		data.clues.down.sort(function(a, b) {
			if (a.col !== b.col) return a.col - b.col;
			return a.row - b.row;
		});

		// Build 5x5 grid structure for display
		data.gridSize = 5;
		for (var r = 1; r <= 5; r++) {
			for (var c = 1; c <= 5; c++) {
				var cellData = {
					row: r,
					col: c,
					isBlank: true,
					userLetter: '',
					correctLetter: null
				};

				// Check if any word occupies this cell
				for (var i = 0; i < data.words.length; i++) {
					var word = data.words[i];
					var wordRow = word.row;
					var wordCol = word.col;

					if (word.direction === 'horizontal') {
						if (wordRow === r && wordCol <= c && c < wordCol + word.length) {
							cellData.isBlank = false;
							cellData.correctLetter = word.word[c - wordCol];
							break;
						}
					} else { // vertical
						if (wordCol === c && wordRow <= r && r < wordRow + word.length) {
							cellData.isBlank = false;
							cellData.correctLetter = word.word[r - wordRow];
							break;
						}
					}
				}

				data.grid.push(cellData);
			}
		}
	}
})();
